const STORAGE='qf-python-practice-v1', $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let exercises=[],checkerSource='',selected=null,worker=null,busy=false,timer=null,active=null,sequence=0,storageOK=true;
let record={version:1,items:{},attempts:[]};
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved?.version===1&&saved.items&&typeof saved.items==='object'&&!Array.isArray(saved.items)&&Array.isArray(saved.attempts))record=saved;}catch{storageOK=false;}
for(const a of record.attempts)if(a&&a.status==='running')a.status='interrupted';
function item(id=selected.id){if(!record.items[id]||typeof record.items[id]!=='object'||Array.isArray(record.items[id]))record.items[id]={};const p=record.items[id],ex=exercises.find(e=>e.id===id);for(const[k,fallback]of Object.entries({code:ex.starter,prediction:'',reflection:'',confidence:'',output:''}))if(typeof p[k]!=='string')p[k]=fallback;if(!Array.isArray(p.checks)||!p.checks.every(c=>c&&typeof c.label==='string'&&typeof c.passed==='boolean'&&typeof c.message==='string'))p.checks=null;if(typeof p.checkedCode!=='string')p.checkedCode=null;p.done=p.done===true&&p.checkedCode===p.code&&p.checks?.length===ex.cases.length&&p.checks.every(c=>c.passed)&&p.reflection.trim().length>=30&&p.prediction.trim().length>=10;return p;}
function save(){record.updated=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(record));storageOK=true;}catch{storageOK=false;}const statusText=storageOK?'Saved on this device':'Saving unavailable · export before leaving';if($('#storage-status').textContent!==statusText)$('#storage-status').textContent=statusText;renderNav();}
function renderNav(){if(!exercises.length)return;$('#activities').innerHTML=[...new Set(exercises.map(e=>e.chapter))].map(chapter=>`<div class="group-label">CHAPTER ${chapter} · ${exercises.filter(e=>e.chapter===chapter).reduce((n,e)=>n+e.minutes,0)} EXTRA MINUTES</div>${exercises.filter(e=>e.chapter===chapter).map(e=>`<a href="#${e.id}" ${e.id===selected?.id?'aria-current="step"':''} class="${item(e.id).done?'done':''}"><span class="step-icon" aria-hidden="true">${item(e.id).done?'✓':'Py'}</span><span>${e.title}<small>${e.kind} · ${e.minutes} min</small></span></a>`).join('')}`).join('');}
function feedback(text,error=false){$('#consolidation-feedback').textContent=text;$('#consolidation-feedback').className='feedback'+(error?' error':'');$('#consolidation-feedback').setAttribute('tabindex','-1');$('#consolidation-feedback').focus();}
function setStatus(text){$('#runtime-status').textContent=text;}
function setBusy(value){busy=value;for(const el of document.querySelectorAll('[data-action="run"],[data-action="check"],[data-action="example"],[data-action="reset-code"],[data-action="solution"]'))el.disabled=value;$('#stop').disabled=!value;$('#code').readOnly=value;}
function showChecks(){const p=item();$('#checks').innerHTML=p.checks?`<p><strong>${p.checks.filter(c=>c.passed).length}/${p.checks.length} numerical checks matched.</strong> Explain and critique the result before saving.</p>${p.checks.map(c=>`<div class="check-row"><strong>${c.passed?'✓ Matched':'Revisit'} · ${esc(c.label)}</strong><p>${esc(c.message)}</p></div>`).join('')}`:'<p class="mini">No current checks. Edit the script, then check it on changed inputs.</p>';}
function render(){const p=item(),index=exercises.indexOf(selected),chapterHref=selected.chapter===1?'../index.html':`../chapter-${String(selected.chapter).padStart(2,'0')}/index.html`;$('#lesson').innerHTML=`<div class="eyebrow">CHAPTER ${selected.chapter} · PYTHON CONSOLIDATION</div><h1>${esc(selected.title)}</h1><p class="lead">${esc(selected.objective)}</p><div class="exercise-meta"><span class="badge">${esc(selected.kind)}</span><span class="pill">${selected.minutes} optional extra minutes</span><span class="pill">Real Python · no installation</span></div><a class="lesson-link" href="${chapterHref}">← Back to Chapter ${selected.chapter}</a><div class="split-instructions"><section class="panel"><h2>Predict before you execute.</h2><p>${esc(selected.prediction)}</p><label class="field" for="prediction">Your prediction and reason</label><textarea id="prediction" data-save placeholder="I predict … because …">${esc(p.prediction)}</textarea><label class="field" for="confidence">Confidence (ungraded)</label><select id="confidence" data-save><option value="">Choose if useful</option>${['Unsure','Somewhat confident','Confident'].map(v=>`<option ${p.confidence===v?'selected':''}>${v}</option>`).join('')}</select></section><aside class="help-card"><h2>Read the Python.</h2><p>${esc(selected.syntax)}</p><p class="notice">The financial concept comes first. Core chapter completion is separate from this optional coding route.</p></aside></div><section class="panel"><h2>Worked example</h2><p>Trace this small example before editing your script. It is separate from your saved starter.</p><pre class="code-block">${esc(selected.example)}</pre><button data-action="example" class="secondary">Run worked example</button><p class="mini">${selected.id==='ch1-change'?'This first activity supplies a complete reference function; checking it is not independent coding evidence.':'Use the example to identify the method, then complete your own function on the new case below.'}</p></section><section class="editor-panel"><div class="editor-tools"><h2>Your Python script</h2><a href="scripts/${selected.id}.py" download>Download original starter .py</a><button data-action="download-code" class="text-button">Download my edited .py</button></div><p>${esc(selected.instructions)}</p><label class="field" for="code">Editable Python code</label><p id="editor-help" class="mini">Replace TODO lines. Use four spaces for indentation. Tab moves to the next control; it is not captured. Run uses fresh variables each time. Maximum 20,000 characters.</p><textarea class="code-editor" id="code" data-save aria-describedby="editor-help" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="20000" wrap="off">${esc(p.code)}</textarea><div class="run-toolbar"><button data-action="run">Run my script ↗</button><button data-action="check" class="secondary">Check my script</button><button id="stop" class="stop" disabled>Stop Python</button><button data-action="reset-code" class="secondary">Reset to starter</button></div><div id="runtime-status" class="runtime-status" role="status">Python loads only when you run. First loading may take a minute.</div><p class="notice">The runtime downloads from jsDelivr; the supplied code runs on this device in a worker. No course execution server receives it. Each execution stops after five seconds; you can stop loading or execution at any time. If loading fails, <a href="learner-pack.zip" download>use the downloadable local pack</a>.</p><h3>Console output</h3><pre id="output" class="console" tabindex="0" aria-label="Python console output">${esc(p.output||'Your output will appear here.')}</pre><h3>Numerical feedback</h3><div id="checks" aria-live="polite"></div><details class="hint"><summary>Hints: start with the method</summary><ol>${selected.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><details class="hint" id="solution-panel"><summary>Compare with a reference after trying</summary><p>Reference code is deliberately available for formative study. Try and revise first; viewing a solution does not establish independent coding proficiency.</p><button data-action="solution" class="secondary">Reveal reference code</button><pre id="solution-code" class="code-block hidden"></pre><a href="reference/${selected.id}.py" download>Download reference separately</a></details></section><section class="panel"><h2>Explain, revise and consolidate.</h2><p>${esc(selected.reflection)}</p><label class="field" for="reflection">Your explanation and revision</label><textarea id="reflection" data-save placeholder="My output shows … I changed or checked … One limitation is …">${esc(p.reflection)}</textarea><div class="actions"><button data-action="save-reflection">Save consolidation</button><button data-action="export" class="secondary">Export Python learning record ↗</button></div><div id="consolidation-feedback" class="feedback" role="status">${p.done?'Consolidation saved: matched checks and your self-reviewed explanation.':''}</div><p class="notice">Predictions and explanations are self-reviewed; minimum lengths check completeness only. These checks cover a few declared inputs and cannot certify general code correctness, finance research quality or investment performance. No return-based marks or credentials are awarded.</p></section><div class="exercise-next">${index?`<a href="#${exercises[index-1].id}">← Previous Python activity</a>`:'<a href="guide.html">Python setup & text guide</a>'}${index<exercises.length-1?`<a href="#${exercises[index+1].id}">Next: ${esc(exercises[index+1].title)} →</a>`:`<a href="${chapterHref}#finish">Back to the Chapter ${selected.chapter} card →</a>`}</div><p class="source-note">Runtime: Pyodide 314.0.7, loaded on demand. All scripts use only Python's standard library. <a href="guide.html">Local setup, retention, troubleshooting and text route</a>.</p>`;showChecks();renderNav();document.title=`${selected.title} · Python practice`;save();}
function stop(reason='Stopped. Your script and earlier attempts remain saved.'){if(worker)worker.terminate();worker=null;clearTimeout(timer);if(active){active.attempt.status='stopped';active.attempt.message=reason;active=null;}if(selected&&$('#code')){setBusy(false);setStatus(reason);}save();}
async function execute(mode){if(busy)return;const p=item();if(mode!=='example'&&p.prediction.trim().length<10){setStatus('Write a prediction and reason (at least 10 characters) before running your practice code.');$('#prediction').focus();return;}const code=mode==='example'?selected.example:p.code;if(!code.trim()||code.length>20000){setStatus('Enter a script of 1–20,000 characters.');return;}const id=++sequence,attempt={exercise:selected.id,mode,code,prediction:p.prediction,time:new Date().toISOString(),status:'running'};record.attempts.push(attempt);active={id,exercise:selected.id,code,mode,attempt};p.output='';$('#output').textContent='';setBusy(true);setStatus('Loading Python if needed… You can stop at any time.');save();try{if(!worker){worker=new Worker('./worker.js',{type:'module'});worker.onmessage=handleMessage;worker.onerror=()=>{stop('Python could not load or the worker failed. Retry, or download the scripts and use local Python.');};}timer=setTimeout(()=>stop('Runtime loading exceeded one minute. Check your connection or use the local pack.'),60000);worker.postMessage({id,code,mode,cases:selected.cases,checkerSource});}catch(error){stop('Unable to start Python: '+String(error.message)+'. Use the local pack if needed.');}}
function handleMessage(event){const msg=event.data;if(!active||msg.id!==active.id)return;const p=item(active.exercise);if(msg.type==='loading'){setStatus('Downloading and preparing Python… The editor stays available after loading; Stop cancels it.');return;}if(msg.type==='running'){clearTimeout(timer);timer=setTimeout(()=>stop('Execution stopped after five seconds. Check for a loop without an end condition, then revise.'),5000);setStatus(active.mode==='check'?'Checking named functions on changed inputs…':'Running in a fresh Python namespace…');return;}if(msg.type==='output'){p.output=(p.output+msg.text).slice(0,12500);$('#output').textContent=p.output;return;}clearTimeout(timer);if(msg.type==='done'){active.attempt.status='finished';active.attempt.results=msg.results;active.attempt.pythonVersion=msg.pythonVersion;if(active.mode==='check'){p.checks=msg.results;p.checkedCode=active.code;p.done=false;showChecks();}if(!p.output){p.output=active.mode==='check'?'Checks completed. See the numerical feedback below.':'The script finished with no printed output. Use print(...) to display a value.';$('#output').textContent=p.output;}setStatus(`Finished using Python ${msg.pythonVersion}. ${active.mode==='example'?'This was the worked example; your edited script is unchanged.':'Explain the result, then check or revise your script.'}`);}else if(msg.type==='error'){active.attempt.status='error';active.attempt.error=msg.text;p.output+=`${p.output?'\n':''}${msg.text}`;$('#output').textContent=p.output;setStatus('Python reported an error. Read its last line, check the hints, then revise and retry.');}active=null;setBusy(false);save();}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-save]')||!selected)return;const p=item();p[el.id]=el.value;if(el.id!=='confidence')p.done=false;if(el.id==='code'){p.checkedCode=null;p.checks=null;showChecks();setStatus('Code changed. Run and check it again; previous console output is from an earlier run.');}if(el.id!=='confidence')$('#consolidation-feedback').textContent='Work changed. Check the script and save your reflection again.';save();});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||!selected)return;const action=button.dataset.action,p=item();if(['run','check','example'].includes(action))execute(action);if(action==='reset-code'){p.code=selected.starter;p.checks=null;p.checkedCode=null;p.done=false;p.output='';render();$('#code').focus();setStatus('Starter restored. Earlier attempts are retained.');}if(action==='download-code')download(selected.id+'.py',p.code,'text/x-python');if(action==='export'){download('qf-python-learning-record.json',JSON.stringify({...record,exportedAt:new Date().toISOString(),notice:'Formative self-study; prose self-reviewed; no credential.'},null,2),'application/json');setStatus('Learning record export initiated. It contains your code, prose and attempts.');}if(action==='solution'){const exerciseId=selected.id;try{const response=await fetch(`reference/${exerciseId}.py`);if(!response.ok)throw Error('Reference not found');const reference=await response.text();if(selected.id!==exerciseId)return;$('#solution-code').textContent=reference;$('#solution-code').classList.remove('hidden');p.viewedReference=true;save();}catch{setStatus('Reference could not load. Try its separate download link or retry.');}}if(action==='save-reflection'){if(busy)return feedback('Wait for Python to finish before saving a consolidation.',true);if(!p.checks?.every(c=>c.passed)||p.checks.length!==selected.cases.length||p.checkedCode!==p.code)return feedback('Check your current script and correct all supplied numerical cases before saving.',true);if(p.prediction.trim().length<10||p.reflection.trim().length<30)return feedback('Write a prediction and at least 30 characters explaining a correction/check and a limitation. These are completeness checks; self-review the reasoning.',true);p.done=true;save();feedback(selected.kind==='Worked example'?'Reference example consolidated. This confirms the supplied function and your self-reviewed reflection, not independent coding proficiency.':'Consolidation saved. Tests matched and your self-reviewed explanation is recorded.');}});
function navigate(){const hash=location.hash.slice(1);if(hash==='lesson'){ $('#lesson').focus();return;}const chapter=new URLSearchParams(location.search).get('chapter');const next=exercises.find(e=>e.id===hash)||exercises.find(e=>String(e.chapter)===chapter)||exercises[0];if(busy)stop('Activity changed; the previous execution was stopped.');selected=next;render();$('#lesson').focus();window.scrollTo({top:0,behavior:'instant'});}
$('#privacy').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#close-privacy').addEventListener('click',()=>$('#privacy-dialog').close());$('#clear-record').addEventListener('click',()=>{if(!confirm('Delete all Python-practice code, prose, checks and attempts from this browser? Core chapters and downloaded files remain.'))return;stop('Python stopped for reset.');record={version:1,items:{},attempts:[]};$('#privacy-dialog').close();render();setStatus('Python practice reset. Core chapter records were not changed.');});document.addEventListener('click',e=>{if(e.target.id==='stop')stop();});
try{const [spec,source]=await Promise.all([fetch('exercises.json'),fetch('checker.py')]);if(!spec.ok||!source.ok)throw Error('Activity files unavailable');exercises=await spec.json();checkerSource=await source.text();navigate();window.addEventListener('hashchange',navigate);}catch{$('#lesson').innerHTML='<h1>Python activity files could not load.</h1><p>Reload this page, or use the <a href="learner-pack.zip">local learner pack</a> and <a href="guide.html">text instructions</a>.</p>';}
